$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$migration = Decode ""
$refundHelper = Decode ""
$cancellationApi = Decode ""
$cancellationCard = Decode ""
$refundImportOld = Decode "aW1wb3J0IHR5cGUgU3RyaXBlIGZyb20gInN0cmlwZSI7"
$refundImportNew = Decode "aW1wb3J0IHR5cGUgU3RyaXBlIGZyb20gInN0cmlwZSI7CmltcG9ydCB7CiAgdHJ5UmVjb25jaWxlQm9va2luZ0dyb3VwU3RyaXBlUmVmdW5kLAp9IGZyb20gIkAvbGliL3N0cmlwZS1ncm91cC1yZWZ1bmRzIjs="
$refundFunctionOld = Decode "ZXhwb3J0IGFzeW5jIGZ1bmN0aW9uIHJlY29uY2lsZVN0cmlwZVJlZnVuZCgKICByZWZ1bmQ6IFN0cmlwZS5SZWZ1bmQKKTogUHJvbWlzZTx2b2lkPiB7"
$refundFunctionNew = Decode ""
$checkoutSelectOld = Decode "aWQsIG1hcmtldF9yZXF1ZXN0X2lkLCBjbGllbnRfcHJvZmlsZV9pZCwgcHJvdmlkZXJfcHJvZmlsZV9pZCwgdXNlcl9zZXJ2aWNlX2lkLCBzdGF0dXMsIHBheW1lbnRfc3RhdHVzLCB0b3RhbF9hbW91bnRfY2VudHMsIGN1cnJlbmN5LCBwYXltZW50X21vZGUsIGFwcGxpY2F0aW9uX2ZlZV9hbW91bnQsIHN0cmlwZV9jaGVja291dF9zZXNzaW9uX2lk"
$checkoutSelectNew = Decode ""
$checkoutAnchor = Decode "ICAgIGlmICgKICAgICAgZ3JvdXAuc3RhdHVzICE9PQogICAgICAiYWNjZXB0ZWQiCiAgICApIHs="
$checkoutGuard = Decode ""

$migrationPath = Join-Path $root "supabase\migrations\20260812211800_klyx_group_cancellation_resolution_12_90.sql"
$helperPath = Join-Path $root "lib\stripe-group-refunds.ts"
$apiPath = Join-Path $root "app\api\booking-groups\[id]\cancellation\route.ts"
$cardPath = Join-Path $root "app\booking-groups\[id]\GroupCancellationCard.tsx"
$refundPath = Join-Path $root "lib\stripe-refunds.ts"
$checkoutPath = Join-Path $root "app\api\stripe\create-group-checkout-session\route.ts"

foreach ($path in @($apiPath, $cardPath, $refundPath, $checkoutPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "12.90 : fichier requis introuvable : $path"
    }
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

foreach ($path in @($apiPath, $cardPath, $refundPath, $checkoutPath)) {
    Copy-Item -LiteralPath $path -Destination ($path + ".bak-12-90-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($migrationPath, $migration, $utf8)
[System.IO.File]::WriteAllText($helperPath, $refundHelper, $utf8)
[System.IO.File]::WriteAllText($apiPath, $cancellationApi, $utf8)
[System.IO.File]::WriteAllText($cardPath, $cancellationCard, $utf8)

$refundRouter = [System.IO.File]::ReadAllText($refundPath)

if (-not $refundRouter.Contains("KLYX_GROUP_REFUND_ROUTER_12_90")) {
    if (-not $refundRouter.Contains($refundImportOld)) {
        throw "12.90 : import stripe-refunds introuvable."
    }

    $refundRouter = $refundRouter.Replace($refundImportOld, $refundImportNew)

    if (-not $refundRouter.Contains($refundFunctionOld)) {
        throw "12.90 : reconcileStripeRefund introuvable."
    }

    $refundRouter = $refundRouter.Replace($refundFunctionOld, $refundFunctionNew)
}

[System.IO.File]::WriteAllText($refundPath, $refundRouter, $utf8)

$checkout = [System.IO.File]::ReadAllText($checkoutPath)

if (-not $checkout.Contains("KLYX_GROUP_CANCEL_PAYMENT_GUARD_12_90")) {
    if (-not $checkout.Contains($checkoutSelectOld)) {
        throw "12.90 : select groupe Checkout introuvable."
    }

    $checkout = $checkout.Replace($checkoutSelectOld, $checkoutSelectNew)

    if (-not $checkout.Contains($checkoutAnchor)) {
        throw "12.90 : ancre Checkout introuvable."
    }

    $checkout = $checkout.Replace($checkoutAnchor, $checkoutGuard)
}

[System.IO.File]::WriteAllText($checkoutPath, $checkout, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.90 APPLIQUE"
Write-Host "======================================"
Write-Host "Accord deux participants : OK"
Write-Host "Auto-approbation : BLOQUEE"
Write-Host "Remboursement Stripe unique : OK"
Write-Host "Reverse transfer : OK"
Write-Host "Commission KLYX : REMBOURSEE"
Write-Host "Creneaux enfants : SYNCHRONISES"
Write-Host "======================================"
